UPDATE products SET detail = $detail${"hero":{"tag":"INDOOR FIXED LED","image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780562927477_i3w0yl_ChatGPT_Image_2026__6__4_____05_48_38.png","title":"S-Poster","summary":[],"cta_link":"/contact","title_en":"S-Poster","cta_label_en":"Get a Quote","cta_label_ko":"견적 문의","description_en":"An LED display supporting various installation modes — standalone, ceiling-mounted, wall-mounted, and multi-screen. Made of slim, lightweight aluminum die-casting, it can be installed easily and conveniently wherever the user wants.","description_ko":"단독형, 천정 부착형, 벽 부착형, 멀티 스크린 등 다양한 설치 모드를 지원하는 LED Display 제품으로 슬림하고 가벼운 알루미늄 다이캐스팅 소재로 만들어져 사용자가 원하는 곳에 쉽고 간편하게 설치가 가능합니다."},"specs":[{"label":"Model","value":"S-Poster"},{"label":"Pixel Pitch (mm)","value":"2.5"},{"label":"Unit Dimensions [W×H×D] (mm)","value":"640  1920 X 39"},{"label":"Unit Resolution [W×H] (pixels)","value":"256 X 768"},{"label":"Module Size [W×H] (mm)","value":"320 X 160"},{"label":"Brightness (nit)","value":"800"},{"label":"Refresh (Hz)","value":"3840"},{"label":"Viewing Angle [H/V] (°)","value":"160 / 160"},{"label":"Unit Weight (kg)","value":"32"},{"label":"Power Consumption [Max.] (W/㎡)","value":"600"},{"label":"Maintenance","value":"Front"}],"banner":{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780635241763_n1ifkk_sp1.png","title_en":"","title_ko":"","description_en":"","description_ko":""},"gallery":{"images":["https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780634915227_f9lb5n_3-1.png"],"options":["P2.5"],"title_en":"S-Poster","title_ko":"S-Poster","subtitle_en":"Mobile LED Display","description_en":"A stand-type LED display and All-In-One system that lets you create, broadcast, and manage advertising content anytime, anywhere using a PC or smartphone, and manage multiple display devices from a single device.","description_ko":"스탠드형 LED Display제품으로 PC 및 스마트폰을 이용해 언제 어디서나 광고 콘텐츠를 제작, 송출, 관리가 가능하며, 여러 대의 디스플레이 장치를 하나의 디바이스로 관리할 수 있는 All-In-One System 제품입니다.","options_label_en":"Pixel Pitch","options_label_ko":"픽셀 피치"},"features":[{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780619202629_r34afj_01_UltraSlim_600x400.png","title_en":"Digital signage realized with a thin and lightweight structure","title_ko":"얇고 가벼운 구조로 구현한 \n디지털 사이니지","subtitle_en":"공간 활용도를 극대화하는 슬림 설계","description_en":"An ultra-slim design and lightweight structure minimize installation space constraints. By effectively reducing thickness and weight, it is easy to transport and install, creating a clean display environment in various spaces such as store entrances, shopping malls, exhibition halls, and hotel lobbies.","description_ko":"설치 공간의 제약을 최소화하기 위해 초슬림 디자인과 경량 구조를 적용했습니다. 두께와 무게를 효과적으로 줄여 운반과 설치가 간편하며, 매장 입구, 쇼핑몰, 전시장, 호텔 로비 등 다양한 공간에서 깔끔한 디스플레이 환경을 구현할 수 있습니다."},{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780619214664_8kgnpu_02_CableFree_QuickInstallation_600x400.png","title_en":"Easy installation completed with a cable-free structure","title_ko":"Cable Free 구조로 완성하는 \n손쉬운 시공","subtitle_en":"빠르고 효율적인 설치 솔루션","description_en":"A structure that can be installed quickly without complex cable connections. A simple coupling system shortens construction time and improves installation convenience, and quick separation and reassembly are possible during maintenance.","description_ko":"복잡한 케이블 연결 작업 없이 빠르게 설치할 수 있는 구조를 적용했습니다. 간편한 결합 시스템을 통해 시공 시간을 단축하고 설치 편의성을 높였으며, 유지보수 시에도 신속한 분리와 재조립이 가능합니다."},{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780619369016_v7xnc0_03_VariousInstallationModes_600x400_v2.png","title_en":"An installation solution applicable to various environments","title_ko":"다양한 환경에 적용 가능한 설치 솔루션","subtitle_en":"공간에 맞춘 유연한 디스플레이 구성","description_en":"Supporting various installation methods such as freestanding stand, wall-mounted, ceiling-mounted, and multi-screen, it enables digital signage optimized for the space and purpose. It enables effective information delivery and advertising in diverse environments such as stores, exhibition halls, and public facilities.","description_ko":"독립형 스탠드, 벽걸이형, 천장형, 멀티 스크린 등 다양한 설치 방식을 지원하여 공간과 목적에 최적화된 디지털 사이니지 구성이 가능합니다. 매장, 전시장, 공공시설 등 다양한 환경에서 효과적인 정보 전달과 광고 연출이 가능합니다."},{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780618893368_a5mzzn_04_SmartRealtimeManagement_noborder_1__600x400.png","title_en":"More efficient display operation with real-time content management","title_ko":"실시간 콘텐츠 관리로 \n더욱 효율적인 디스플레이 운영","subtitle_en":"언제 어디서나 손쉬운 운영","description_en":"A smart management system lets you easily manage content via PC and mobile devices. Images, videos, and promotional content can be updated in real time, improving operational efficiency and effectively supporting various marketing activities.","description_ko":"PC와 모바일 기기를 통해 콘텐츠를 손쉽게 관리할 수 있는 스마트 관리 시스템을 제공합니다. 이미지, 영상, 프로모션 콘텐츠 등을 실시간으로 업데이트할 수 있어 운영 효율성을 높이고 다양한 마케팅 활동을 효과적으로 지원합니다."},{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780618888808_5b1l3r_05_PlugAndPlay_noborder_1__600x400.png","title_en":"An all-in-one solution ready to use without complex setup","title_ko":"복잡한 설정 없이 바로 사용하는 \n올인원 솔루션","subtitle_en":"누구나 쉽게 사용할 수 있는 디지털 사이니지","description_en":"It supports Plug & Play, ready to use simply by connecting power. Content can be played quickly without complex setup, and digital signage can be operated easily without specialized technical knowledge.","description_ko":"전원 연결만으로 즉시 사용할 수 있는 Plug & Play 방식을 지원합니다. 별도의 복잡한 설정 과정 없이 빠르게 콘텐츠를 재생할 수 있으며, 전문적인 기술 지식 없이도 손쉽게 디지털 사이니지를 운영할 수 있습니다."}],"cta_section":{"title_en":"From consultation to design and installation — a customized LED display solution","title_ko":"제품 상담부터 설계·시공까지, 맞춤형 LED 디스플레이 솔루션","description_en":"Request a quote now and get a personalized consultation.","description_ko":"지금 견적 문의하시고 맞춤 상담을 받아보세요."},"applications":[]}$detail$::jsonb WHERE id = 66;

