UPDATE products SET detail = $detail${"hero":{"tag":" OUTDOOR FIXED LED","image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780630912058_7v1z65_ChatGPT_Image_2026__6__5_____12_41_26.png","title":"SOD-T","summary":[],"cta_link":"/contact","title_en":"SOD-T","cta_label_en":"Get a Quote","cta_label_ko":"견적 문의","description_en":"It clearly displays advertising and business content without being affected by outdoor sunlight, ambient light, or weather.\nIts large size maximizes advertising exposure to capture customers' attention, and it offers stable durability built for long-term use — an outdoor LED display solution.","description_ko":"옥외 환경의 태양광, 주변 조명, 날씨 등에 영향을 받지 않고 \n광고 비지니스 콘텐츠를 선명하게 표출합니다.\n대형 사이즈로 광고 노출을 극대화해 고객들의 시선을 사로잡을 수 있고 \n장기간 사용에 대비하여 안정적인 내구성까지 보유한 실외용 LED디스플레이 솔루션입니다."},"specs":[{"label":"Model","value":"ST-3 / ST-4 / ST-6"},{"label":"Pixel Pitch (mm)","value":"3.91 / 4.81 / 6.25"},{"label":"Cabinet Dimensions [WxHxDJ(mm)","value":"1000 X 1000 X 83"},{"label":"Cabinet Resolution [WxHJlpixels)","value":"256 X 256 / 208 X 208 / 160 X 160"},{"label":"Module Size [WxH](mm)","value":"500 X 250"},{"label":"Brightness (nit)","value":"4500 ~ 6500"},{"label":"Refresh (Hz)","value":"1920 / 3840"},{"label":"Viewing Angle [H/V](°)","value":"160 / 140"},{"label":"Cabinet Weight (kg)","value":"22.5"},{"label":"Power Consumption [Max.](W/m )","value":"650"},{"label":"Maintenance","value":"Front & Rear"},{"label":"IP Rating","value":"IP65"}],"banner":{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780631549770_h13fss_ChatGPT_Image_2026__6__5_____12_52_25.png","title_en":"","title_ko":"","description_en":"","description_ko":""},"gallery":{"images":["https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780631165775_la7vxd_2.png","https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780631166324_uwimpp_3.png","https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780631166497_r3xt96_4.jpg","https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780631166932_is91vd_5-1.png","https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780631167795_6sjprs_5-2.png"],"options":["P3.91","P4.81","P6.25"],"title_en":"SOD-T","title_ko":"SOD-T","subtitle_en":"Outdoor Fixed LED Display","description_en":"An outdoor LED display that renders clear advertising content even in diverse outdoor environments such as sunlight, ambient light, and weather. Its large screen and outstanding durability maximize advertising exposure and enable stable long-term operation.","description_ko":"태양광, 주변 조명, 날씨 등 다양한 옥외 환경에서도 선명한 광고 콘텐츠를 구현하는 \n실외용 LED 디스플레이 제품으로 대형 화면과 뛰어난 내구성으로 광고 노출 효과를 \n극대화하며 장기간 안정적인 운영이 가능합니다.","options_label_en":"Pixel Pitch","options_label_ko":"픽셀 피치"},"features":[{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780626441781_9rvdej_ChatGPT_Image_2026__6__5_____11_26_07.png","title_en":"Powerful waterproofing that protects from front to rear","title_ko":"전면부터 후면까지 보호하는 \n강력한 방수 성능","subtitle_en":"혹독한 옥외 환경에서도 안정적인 운영","description_en":"Waterproof design is applied not only to the front but also to the rear cabinet so that stable performance is maintained regardless of the installation environment. It protects internal components from rain, snow, and humidity, providing high reliability and durability even in long-term outdoor operation.","description_ko":"설치 환경에 관계없이 안정적인 성능을 유지할 수 있도록 전면뿐 아니라 후면 캐비닛까지 방수 설계를 적용했습니다. 비, 눈, 습기 등 다양한 외부 환경으로부터 내부 부품을 보호하며, 장시간 옥외 운영 환경에서도 높은 신뢰성과 내구성을 제공합니다."},{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780629796932_keouv1_ChatGPT_Image_2026__6__5_____12_22_57.png","title_en":"An outdoor LED display completed with a light and slim design","title_ko":"가볍고 슬림한 디자인으로 완성한 \n옥외 LED 디스플레이","subtitle_en":"설치 효율성과 공간 활용성을 높인 설계","description_en":"An aluminum die-casting structure achieves both outstanding rigidity and light weight. Product transport and installation are more convenient, and reduced structural load improves construction efficiency. Stable, clean installation is possible in a variety of outdoor environments.","description_ko":"알루미늄 다이캐스팅 구조를 적용하여 뛰어난 강성과 경량화를 동시에 실현했습니다. 제품 운반과 설치가 더욱 편리하며 구조물 하중을 줄여 시공 효율성을 향상시킵니다. 다양한 옥외 환경에서도 안정적이고 깔끔한 설치가 가능합니다."},{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780629803121_ktgrb2_ChatGPT_Image_2026__6__5_____11_15_06.png","title_en":"More convenient management with front & rear maintenance","title_ko":"Front & Rear Maintenance로 더욱 편리한 관리","subtitle_en":"다양한 설치 환경을 고려한 유지관리 시스템","description_en":"A structure that allows maintenance from both the front and rear enables flexible upkeep depending on the installation environment. Quick inspection and parts replacement are possible even in confined spaces, shortening maintenance time and maximizing operational efficiency.","description_ko":"전면과 후면 모두에서 유지보수가 가능한 구조를 적용하여 설치 환경에 따라 유연한 유지관리가 가능합니다. 제한된 공간에서도 신속한 점검과 부품 교체가 가능하며, 유지보수 시간을 단축하여 운영 효율성을 극대화합니다."},{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780629816363_0i5hle_ChatGPT_Image_2026__6__5_____11_12_56.png","title_en":"Simple installation with a precise Fast Lock structure","title_ko":"정밀한 Fast Lock 구조로 \n간편한 설치 구현","subtitle_en":"빠르고 정확한 캐비닛 결합 방식","description_en":"A high-precision Lock System enables fast and stable fastening between cabinets. It shortens installation time and improves construction accuracy, providing uniform flatness and excellent structural stability even when building large LED displays.","description_ko":"고정밀 Lock System을 적용하여 캐비닛 간 빠르고 안정적인 체결이 가능합니다. 설치 시간을 단축하고 시공 정확도를 향상시키며, 대형 LED 디스플레이 구축 시에도 균일한 평탄도와 뛰어난 구조 안정성을 제공합니다."},{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780630679124_5f2anq_ChatGPT_Image_2026__6__5_____12_37_51.png","title_en":"An immersive display completed with right-angle installation","title_ko":"Right-angle installation으로 \n완성하는 몰입형 디스플레이","subtitle_en":"창의적인 공간 연출을 위한 유연한 설계","description_en":"The right-angle installation design enables seamless 90° corner configurations, expanding digital signage applications beyond conventional flat displays. Ideal for building corners, commercial spaces, and exhibition environments, it creates a distinctive visual impact while maximizing space utilization.","description_ko":"90° 직각 설치를 지원하는 캐비닛 구조 설계를 통해 코너 구간에서도 끊김 없는 디스플레이 구성이 가능합니다. 건축물 외벽, 쇼핑몰, 전시장 및 다양한 상업 공간의 모서리에 적용하여 공간의 입체감을 극대화하고 시인성을 향상시킵니다."}],"cta_section":{"title_en":"","title_ko":"","description_en":"","description_ko":""},"applications":[]}$detail$::jsonb WHERE id = 67;

