UPDATE products SET detail = $detail${"hero":{"tag":"OUTDOOR FIXED LED","image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780632013355_as5hq7_ChatGPT_Image_2026__6__5_____12_59_55.png","title":"SOD-R","summary":[],"cta_link":"/contact","title_en":"SOD-R","cta_label_en":"Get a Quote","cta_label_ko":"견적 문의","description_en":"Fast installation, outstanding durability, flexible operation.\n\nA quick-lock system minimizes setup and teardown time, and support for various installation modes enables rapid response at any rental site.\nWith strong brightness and front/rear IP65 waterproofing, it is an outdoor rental LED display solution capable of stable content operation in any outdoor environment.","description_ko":"빠른 설치, 뛰어난 내구성, 유연한 운영.\n\n퀵락 시스템으로 설치와 철거 시간을 최소화하고, 다양한 설치 모드를 지원하여 \n모든 렌탈 현장에 신속하게 대응합니다. \n강력한 밝기와 전·후면 IP65 방수 성능으로 어떤 옥외 환경에서도 \n안정적인 콘텐츠 운영이 가능한 실외 렌탈 LED 디스플레이 솔루션입니다."},"specs":[{"label":"Model","value":"SR-2.6 / SR-2.97 / SR-3.91 / 4.81 / SR-5.95 "},{"label":"Pixel Pitch (mm)","value":"2.6 / 2.97 / 3.91 / 4.81 / 5.95"},{"label":"Cabinet Dimensions [WxHxDJ(mm)","value":"500 X 500 X 84.5 / 500 X 1000 X 84.5"},{"label":"Cabinet Resolution [WxHJlpixels)","value":"192 X 192 / 168 X 168 / 128 X 128 / 104 X 104"},{"label":"Module Size [WxH](mm)","value":"250 X 250"},{"label":"Brightness (nit)","value":"4500 ~ 5500"},{"label":"Refresh (Hz)","value":"3840"},{"label":"Viewing Angle [H/V](°)","value":"160 / 160"},{"label":"Cabinet Weight (kg)","value":"8 / 14.5"},{"label":"Power Consumption [Max.](W/m )","value":"800"},{"label":"Maintenance","value":"Front & Rear"},{"label":"IP Rating","value":"IP65"}],"banner":{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780632480814_fy6tbf_ChatGPT_Image_2026__6__5_____01_07_52.png","title_en":"","title_ko":"","description_en":"","description_ko":""},"gallery":{"images":["https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780642403181_tci1b3_38094371-7299-43c4-a481-ca7915c78e3f_removalai_preview.png","https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780642397762_sfp8x5______2026-06-05_155204.png","https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780632064602_0o14ya_3.png","https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780642396835_xdesr1______2026-06-05_155121.png","https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780642397439_l7pvio______2026-06-05_155128.png","https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780642397585_5d5687______2026-06-05_155147.png"],"options":["P2.6","P2.97","P3.91","P4.81","P5.95"],"title_en":"SOD-R","title_ko":"SOD-R","subtitle_en":"Outdoor Fixed LED Display","description_en":"An outdoor LED display that can be installed quickly and accurately with a quick-lock system. Its sturdy cabinet structure and front/rear IP65 waterproof design enable stable operation in various outdoor environments, while its high brightness always delivers clear content.","description_ko":"퀵락 시스템을 적용해 빠르고 정확한 설치가 가능한 실외 LED 디스플레이입니다. \n견고한 캐비닛 구조와 전·후면 IP65 방수 설계로 다양한 옥외 환경에서도 안정적인 \n운영이 가능하며, 고휘도 성능을 통해 언제나 선명한 콘텐츠를 제공합니다.","options_label_en":"Pixel Pitch","options_label_ko":"픽셀 피치"},"features":[{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780639024844_pp2h39_ChatGPT_Image_2026__6__5_____02_56_55.png","title_en":"Flexible screen configuration realized through cabinet combinations","title_ko":"캐비닛 조합으로 구현하는 \n유연한 화면 구성","subtitle_en":"설치 환경에 맞춰 자유롭게 확장되는 디스플레이","description_en":"Supporting two cabinet sizes, 500×500mm and 500×1000mm, it enables display configurations optimized for the installation space and content ratio. Screens of various sizes and shapes can be freely designed, efficiently responding to diverse on-site environments such as advertising, performances, exhibitions, and events.","description_ko":"500×500mm와 500×1000mm 두 가지 캐비닛 규격을 지원하여 설치 공간과 콘텐츠 비율에 최적화된 디스플레이 구성이 가능합니다. \n다양한 크기와 형태의 화면을 자유롭게 설계할 수 있어 광고, 공연, 전시, 이벤트 등 다양한 현장 환경에 효율적으로 대응합니다."},{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780641479011_rk4w8k_ChatGPT_Image_2026__6__5_____03_37_43.png","title_en":"Faster installation and dismantling with the Fast Lock system","title_ko":"Fast Lock 시스템으로 \n더욱 신속한 설치와 해체","subtitle_en":"현장 운영 효율을 높이는 스마트 설계","description_en":"A precise Fast Lock structure enables fast and accurate coupling between cabinets. Quick installation and dismantling without complex work shortens working time at events and rental sites and improves operational efficiency.","description_ko":"정밀한 Fast Lock 구조를 적용하여 캐비닛 간 빠르고 정확한 결합이 가능합니다. \n별도의 복잡한 작업 없이 신속한 설치와 해체가 가능해 행사 및 렌탈 현장에서 작업 시간을 단축하고 운영 효율성을 높여줍니다."},{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780638248158_8txovi_ChatGPT_Image_2026__6__5_____02_43_56.png","title_en":"A free installation solution from flat to curved","title_ko":"평면부터 곡면까지 자유로운 설치 솔루션","subtitle_en":"공간 제약 없이 구현하는 창의적인 디스플레이","description_en":"Supporting various installation methods such as hanging, stack, and curved, it enables configurations optimized for the installation purpose and spatial environment. It can create distinctive visual effects in diverse spaces such as concert halls, exhibition halls, shopping malls, and event stages.","description_ko":"행잉(Hanging), 스택(Stack), 곡면(Curved) 등 다양한 설치 방식을 지원하여 \n설치 목적과 공간 환경에 최적화된 구성이 가능합니다. \n공연장, 전시장, 쇼핑몰, 이벤트 무대 등 다양한 공간에서 차별화된 시각적 효과를 구현할 수 있습니다."},{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780638491836_fts9ng_ChatGPT_Image_2026__6__5_____02_48_05.png","title_en":"IP65-rated front and rear waterproof design","title_ko":"IP65 등급의 전·후면 방수 설계","subtitle_en":"옥외 환경에서도 안정적인 운영 성능","description_en":"With IP65-level waterproof and dustproof design on both the front and rear, it can operate stably in various external environments including rain, dust, and humidity. It is suitable for environments requiring long-term operation such as outdoor advertising, sports stadiums, festivals, and concert venues.","description_ko":"전면과 후면 모두 IP65 수준의 방수·방진 설계를 적용하여 비, 먼지, 습기 등 다양한 외부 환경에서도 안정적으로 운영할 수 있습니다. 옥외 광고, \n스포츠 경기장, 축제 및 공연장 등 장시간 운영이 필요한 환경에 적합합니다."}],"cta_section":{"title_en":"","title_ko":"","description_en":"","description_ko":""},"applications":[]}$detail$::jsonb WHERE id = 68;

UPDATE products SET name_en = 'SMI Series' WHERE id = 70;
UPDATE products SET detail = $detail${"hero":{"tag":"Media Facade","image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780559083656_zh8fy5_m02.JPG","title":"SMI Series","summary":[],"cta_link":"/contact","title_en":"SMI Series","cta_label_en":"Get a Quote","cta_label_ko":"견적 문의","description_en":"A digital signage solution that creates astonishing visual effects while maintaining the natural daylight and transparency of a building's glass surface.\nBy turning the building itself into digital architecture, it creatively displays content such as advertising and media art to enhance the building's aesthetics.","description_ko":"건물 유리 표면의 자연 채광 및 투명도를 유지하면서 놀라운 시각적 효과를 만들어내는 디지털 사이니지 솔루션입니다.\n건물 자체를 디지털 아케텍처화 하여 광고나 미디어아트 등의 콘텐츠를 창의적으로 표출하여 건물의 미학을 향상시킬 수 있습니다."},"specs":[{"label":"Model","value":"SMI-2.6 / SMI-2.8 / SMI-3.9 / SMI-7 / SMI-10"},{"label":"Pixel Pitch (mm)","value":"2.6 / 2.8 / 3.9 / 7.8 / 10"},{"label":"Cabinet Dimensions (WxHxD)(mm)","value":"1,000 X 500 X 43 / 1,000 X 1,000 X 43 "},{"label":"Transparency (%)","value":"50 ~ 80"},{"label":"Brightness (nit)","value":"4,000 ~ 5,000"},{"label":"Refresh (Hz)","value":"1,920"},{"label":"Viewing Angle (H/V) (˚)","value":"140 / 140"},{"label":"Power Consumption (Max)(W/㎡)","value":"800 "},{"label":"Maintenance","value":"Front"}],"banner":{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780560689546_ymj4uy_m03.JPG","title_en":"","title_ko":"","description_en":"","description_ko":""},"gallery":{"images":["https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780560521345_42x743_4-2.png"],"options":["P2.6","P2.8","P3.9","P7.8","P10"],"title_en":"SMI","title_ko":"SMI","subtitle_en":"Media Facade LED Display","description_en":"A transparent LED signage solution that turns a building's exterior into a digital media space.","description_ko":"건물 외관을 디지털 미디어 공간으로 구현하는 투명 LED 사이니지 솔루션","options_label_en":"Pixel Pitch","options_label_ko":"픽셀 피치"},"features":[{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780561043916_s7j0gq_2.jpg","title_en":"High transparency and clear image quality","title_ko":"높은 투과율과 선명한 화질","subtitle_en":"High Transparency& Brightness","description_en":"After installation it provides high transparency of up to 80%, maintaining indoor and outdoor visibility and natural daylight without compromising the building's sense of openness. It also supports brightness of up to 5,000 nits, effectively expressing diverse content with clear, vivid image quality even during the day.","description_ko":"제품 설치 후 최대 80%의 높은 투과율을 제공하여 실내외 시야 확보와 자연채광을 유지할 수 있으며, 건물의 개방감을 해치지 않습니다. 또한 최대 5,000nit의 높은 밝기를 지원해 주간에도 선명하고 생생한 화질로 다양한 콘텐츠를 효과적으로 표현할 수 있습니다."},{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780561238100_9gqn1b_4-1.jpg","title_en":"Simple installation and maintenance system","title_ko":"간편한 설치/유지보수 시스템","subtitle_en":"Quick Installation & Maintenance","description_en":"Designed with a modular structure in which modules and LED strips can each be independently disassembled and replaced, installation is simple, and during maintenance only the necessary parts can be quickly inspected or replaced. This reduces work time and maintenance costs and improves operational efficiency.","description_ko":"모듈과 LED 스트립을 각각 독립적으로 분해 및 교체할 수 있는 모듈형 구조로 설계되어 설치 작업이 간편하며, 유지보수 시 필요한 부분만 신속하게 점검하거나 교체할 수 있습니다. 이를 통해 작업 시간과 유지관리 비용을 절감하고 운영 효율성을 높일 수 있습니다."},{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780561376031_x3r78j_5.jpg","title_en":"Clear high-definition display","title_ko":"선명한 고화질 디스플레이","subtitle_en":"High-Definition & Delicate","description_en":"With a minimum pixel pitch of 2.6mm, it achieves detailed, sharp high-definition images and provides excellent image quality and detail even at close range. It expresses text, images, and video content more clearly, making it suitable for advertising, information delivery, and diverse digital content operation.","description_ko":"최소 픽셀 피치 2.6mm를 적용하여 세밀하고 선명한 고화질 화면 구현이 가능하며, 근거리에서도 뛰어난 화질과 디테일을 제공합니다. 텍스트, 이미지, 영상 콘텐츠를 더욱 선명하게 표현할 수 있어 광고, 정보 전달 및 다양한 디지털 콘텐츠 운영에 적합합니다."}],"cta_section":{"title_en":"","title_ko":"","description_en":"","description_ko":""},"applications":[]}$detail$::jsonb WHERE id = 70;

UPDATE products SET detail = $detail${"hero":{"tag":"Media Facade","image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780614927342_jrgxyb_mo1.png","title":"SMO Series","summary":[],"cta_link":"/contact","title_en":"SMO Series","cta_label_en":"Get a Quote","cta_label_ko":"견적 문의","description_en":"A digital signage solution that creates astonishing visual effects while maintaining the natural daylight and transparency of a building's glass surface.\nBy turning the building itself into digital architecture, it creatively displays content such as advertising and media art to enhance the building's aesthetics.","description_ko":"건물 유리 표면의 자연 채광 및 투명도를 유지하면서 놀라운 시각적 효과를 만들어내는 디지털 사이니지 솔루션입니다.\n건물 자체를 디지털 아케텍처화 하여 광고나 미디어아트 등의 콘텐츠를 창의적으로 표출하여 건물의 미학을 향상시킬 수 있습니다."},"specs":[{"label":"Model","value":"SMO-12(SMD) / SMO-15(SMD) / SMO-15(DIP) / SMO-20(DIP) / SMO-25(DIP)"},{"label":"Pixel Pitch (mm)","value":"12.5 / 15.625 / 15.625 / 20 / 25 "},{"label":"Cabinet Dimensions (WxHxD)(mm)","value":"500 X 1,000 X 62"},{"label":"Transparency (%)","value":"40 ~ 60"},{"label":"Brightness (nit)","value":"5,500 ~ 7,500"},{"label":"Refresh (Hz)","value":"3840"},{"label":"Viewing Angle (H/V) (˚)","value":"140 / 140"},{"label":"Power Consumption (Max.)(W/㎡)","value":"600 "},{"label":"Maintenance","value":"Front & Rear"}],"banner":{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780616938087_boaxlk_mo7.JPG","title_en":"","title_ko":"","description_en":"","description_ko":""},"gallery":{"images":["https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780616511806_to6hxv_mo2.JPG","https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780616686405_gg5zhf_mo3.JPG","https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780616686623_xbn74m_mo4.JPG","https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780616686761_3szv2x_mo5.JPG"],"options":["P12.5","P15.625","P20","P25"],"title_en":"SMO","title_ko":"SMO","subtitle_en":"Media Facade LED Display","description_en":"A transparent LED signage solution that turns a building's exterior into a digital media space.","description_ko":"건물 외관을 디지털 미디어 공간으로 구현하는 투명 LED 사이니지 솔루션","options_label_en":"Pixel Pitch","options_label_ko":"픽셀 피치"},"features":[{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780617428773_u2hoch_mo4.JPG","title_en":"60% transparency LED media facade","title_ko":"투과율 60% LED 미이더파사드","subtitle_en":"Outstanding Transparency","description_en":"An outdoor fixed LED media facade achieving up to 60% transparency, rendering clear, dynamic video content while maintaining openness and daylight. It harmonizes with building exteriors and enables diverse presentations such as advertising, branding, and media art.","description_ko":"최대 60%의 높은 투명도를 구현한 실외 고정형 LED 미디어파사드 제품으로, 개방감과 채광을 유지하면서도 선명하고 역동적인 영상 콘텐츠를 구현합니다. 건축물 외관과 조화를 이루며 광고, 브랜딩, 미디어아트 등 다양한 연출이 가능합니다."},{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780617981271_s0zn08_mo8.JPG","title_en":"Outdoor high-brightness LED display","title_ko":"Outdoor 고휘도 LED 디스플레이","subtitle_en":"High Brightness DIP LED","description_en":"Applying DIP LED technology to achieve up to 7,500 nits of high brightness, it provides excellent visibility even in direct sunlight. It stably renders clear, vivid video content in various environments such as outdoor advertising, electronic billboards, and media facades.","description_ko":"DIP LED 기술을 적용하여 최대 7,500nit의 높은 휘도를 구현한 제품으로, 직사광선이 비치는 환경에서도 뛰어난 시인성을 제공합니다. 옥외 광고, 전광판, 미디어파사드 등 다양한 환경에서 선명하고 생생한 영상 콘텐츠를 안정적으로 표현할 수 있습니다."},{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780618479224_s0r3c8_mo3.JPG","title_en":"Easy and simple maintenance","title_ko":"쉽고 간편한 유지보수","subtitle_en":"Easy Maintenance","description_en":"The front allows modules to be safely removed using a dedicated tool, while the rear is designed so that the fixture can be easily detached by pulling its locking device. A simple maintenance structure shortens inspection and repair time and improves operational efficiency.","description_ko":"전면은 전용 공구를 사용해 모듈을 안전하게 분리할 수 있으며, 후면은 부착부의 고정 장치를 당겨 손쉽게 탈거할 수 있도록 설계되었습니다. 간편한 유지보수 구조를 적용해 점검 및 수리 시간을 단축하고 운영 효율성을 높여줍니다."},{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780618919610_33mgfm_mo9.JPG","title_en":"Ultra-light, ultra-slim design","title_ko":"초경량, 초슬림 디자인 설계","subtitle_en":"Light & Slim Structural Design","description_en":"With a lightweight design of as little as 5.5kg and an ultra-slim thickness of as little as 8.1mm, it effectively reduces the load on installation structures. It can also be applied flexibly even in confined spaces, improving construction convenience and enabling installation optimized for various architectural environments.","description_ko":"최소 5.5kg의 경량 설계와 최소 8.1mm의 초슬림 두께를 구현한 제품으로, 설치 구조물에 가해지는 하중 부담을 효과적으로 줄여줍니다. 또한 제한된 공간에도 유연하게 적용할 수 있어 시공 편의성을 높이고 다양한 건축 환경에 최적화된 설치가 가능합니다."},{"image":"https://urjwwxfhoouxkagezjls.supabase.co/storage/v1/object/public/images/products/1780619393586_qg40fp_mo6.JPG","title_en":"High waterproof and dustproof rating","title_ko":"높은 방수 방진 등급","subtitle_en":"IP High Protection","description_en":"With IP65-rated waterproof and dustproof performance, it can operate stably in various outdoor environments including rain, dust, and humidity. By minimizing the impact of the external environment, it provides high durability and reliability and is advantageous for long-term maintenance.","description_ko":"IP65 등급의 방수·방진 성능을 갖춘 제품으로, 비·먼지·습기 등 다양한 옥외 환경에서도 안정적인 운영이 가능합니다. 외부 환경의 영향을 최소화하여 높은 내구성과 신뢰성을 제공하며 장기간 유지관리에도 유리합니다."}],"cta_section":{"title_en":"","title_ko":"","description_en":"","description_ko":""},"applications":[]}$detail$::jsonb WHERE id = 71;

